<section class="public-payment-status"><a class="public-link" href="{{ $donation->campaign ? route('public.campaigns.show', $donation->campaign->slug) : route('public.home') }}">← Kembali ke campaign</a><div class="public-payment-status__card"><span class="public-payment-status__icon public-payment-status__icon--{{ $status }}">{{ $status === 'paid' ? '✓' : '!' }}</span><span class="public-eyebrow">Status pembayaran</span><h1>{{ $labels[$status][0] }}</h1><p class="public-muted">{{ $labels[$status][1] }}</p><div class="public-payment-status__details"><div><span>Nominal donasi</span><strong>Rp {{ number_format($donation->gross_amount, 0, ',', '.') }}</strong></div><div><span>Campaign</span><strong>{{ $donation->campaign?->title ?? 'Salamaid' }}</strong></div><div><span>Referensi</span><strong>{{ $payment?->order_id ?? $donation->id }}</strong></div><div><span>Waktu</span><strong>{{ $payment?->paid_at?->format('d M Y H:i') ?? $donation->created_at?->format('d M Y H:i') }}</strong></div></div>@if(session('status_message'))<div class="public-form-success">{{ session('status_message') }}</div>@endif @if(session('status_error'))<div class="public-form-error">{{ session('status_error') }}</div>@endif @if($status === 'pending' && $payment?->redirect_url)<a class="public-button" href="{{ $payment->redirect_url }}">Lanjutkan pembayaran →</a><form method="POST" action="{{ URL::temporarySignedRoute('public.payments.status.refresh', now()->addDay(), ['donation' => $donation->id]) }}">@csrf<button class="public-button public-button--outline" type="submit">Cek status lagi</button></form>@elseif($status === 'paid')<button class="public-button" type="button" onclick="window.print()">Cetak receipt</button>@elseif(in_array($status, ['expired','failed'], true))<a class="public-button" href="{{ route('public.campaigns.donate', $donation->campaign?->slug ?? '') }}">Coba donasi lagi</a>@endif</div></section>
